import asyncio, asyncssh, os, pty, fcntl, termios, struct, subprocess, sys

PORT = 2222
MAX_SESSIONS = 8
GAME_DIR = os.path.dirname(os.path.abspath(__file__))
active = 0

def set_winsize(fd, rows, cols):
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0, 0))

class OpenServer(asyncssh.SSHServer):
    def begin_auth(self, username):
        return False

async def handle(process):
    global active
    term = process.get_terminal_type()
    if not term:
        process.stdout.write(b"This game needs a terminal (don't pass a command to ssh).\r\n")
        process.exit(1)
        return
    if active >= MAX_SESSIONS:
        process.stdout.write(b"Server is full, try again later.\r\n")
        process.exit(1)
        return

    active += 1
    loop = asyncio.get_running_loop()
    master, slave = pty.openpty()
    cols, rows, _, _ = process.get_terminal_size()
    set_winsize(master, rows, cols)

    def preexec():
        os.setsid()
        fcntl.ioctl(0, termios.TIOCSCTTY, 0)

    child = subprocess.Popen(
        [sys.executable, "main.py"],
        cwd=GAME_DIR, stdin=slave, stdout=slave, stderr=slave,
        env={"TERM": term, "PATH": os.environ["PATH"], "LANG": "C.UTF-8"},
        preexec_fn=preexec, close_fds=True,
    )
    os.close(slave)

    finished = asyncio.Event()

    def on_output():
        try:
            data = os.read(master, 65536)
        except OSError:
            data = b""
        if data:
            process.stdout.write(data)
        else:
            loop.remove_reader(master)
            finished.set()

    loop.add_reader(master, on_output)

    async def pump_input():
        while True:
            try:
                data = await process.stdin.read(1024)
            except asyncssh.TerminalSizeChanged as e:
                set_winsize(master, e.height, e.width)
                continue
            if not data:
                break
            os.write(master, data)

    inp = asyncio.create_task(pump_input())
    fin = asyncio.create_task(finished.wait())
    try:
        await asyncio.wait({inp, fin}, return_when=asyncio.FIRST_COMPLETED)
    finally:
        inp.cancel(); fin.cancel()
        loop.remove_reader(master)
        if child.poll() is None:
            child.kill()
        child.wait()
        os.close(master)
        active -= 1
        process.exit(0)

async def main():
    await asyncssh.create_server(
        OpenServer, "", PORT,
        server_host_keys=[os.path.join(GAME_DIR, "ssh_host_key")],
        process_factory=handle, encoding=None, line_editor=False,
    )
    await asyncio.Future()

asyncio.run(main())